function renderTable(targetId, tableData) {
  const target = document.getElementById(targetId);
  if (!target || !tableData) return;
  const thead = '<thead><tr>' + tableData.columns.map(c => `<th>${c}</th>`).join('') + '</tr></thead>';
  const tbody = '<tbody>' + tableData.rows.map(row => '<tr>' + tableData.columns.map((_, i) => `<td>${row[i] ?? ''}</td>`).join('') + '</tr>').join('') + '</tbody>';
  target.innerHTML = `<div class="table-wrap"><table>${thead}${tbody}</table></div>`;
}
function setupSwitcher(groupId, targetId, tables, initialKey) {
  const group = document.getElementById(groupId);
  if (!group) return;
  const keys = Object.keys(tables);
  group.innerHTML = keys.map(k => `<button type="button" class="switch-btn" data-key="${k}">${k}</button>`).join('');
  function activate(key) {
    group.querySelectorAll('button').forEach(b => b.classList.toggle('active', b.dataset.key === key));
    renderTable(targetId, tables[key]);
  }
  group.addEventListener('click', e => { if (e.target.matches('button[data-key]')) activate(e.target.dataset.key); });
  activate(initialKey || keys[0]);
}
function setupRocWindow() {
  const imgs = [
    ['assets/imgs/fig_roc_vera220.png','VERA220 ROC curves'],
    ['assets/imgs/fig_roc_tju600.png','TJU600 ROC curves'],
    ['assets/imgs/fig_roc_scut1100.png','SCUT1100 ROC curves'],
    ['assets/imgs/fig_roc_fvusm.png','FV-USM ROC curves'],
    ['assets/imgs/fig_roc_mla.png','SDUMLA-HMT ROC curves']
  ];
  let idx = 0;
  const img = document.getElementById('roc-image');
  const cap = document.getElementById('roc-caption');
  function show() {
    if (!img || !cap) return;
    img.src = imgs[idx][0];
    img.alt = imgs[idx][1];
    cap.textContent = imgs[idx][1];
  }
  document.getElementById('roc-prev')?.addEventListener('click', () => { idx = (idx + imgs.length - 1) % imgs.length; show(); });
  document.getElementById('roc-next')?.addEventListener('click', () => { idx = (idx + 1) % imgs.length; show(); });
  show();
}
document.addEventListener('DOMContentLoaded', () => {
  setupSwitcher('accuracy-switcher', 'accuracy-table', window.AGV_TABLES.accuracy, 'VERA220');
  setupSwitcher('corruption-switcher', 'corruption-table', window.AGV_TABLES.corruption, 'VERA220');
  setupSwitcher('attack-switcher', 'attack-table', window.AGV_TABLES.attacks, 'TJU600');
  renderTable('calibration-table', window.AGV_TABLES.calibration.All);
  setupRocWindow();
});
